from itertools import islice

def summarize_dict(d: dict, max_items: int = 5) -> str:
    """Return a compact, single-line preview of a dictionary."""
    if not d:
        return "dict: 0 items"

    preview = ", ".join(
        f"{key!r}: {value!r}"
        for key, value in islice(d.items(), max_items)
    )

    remaining = len(d) - max_items
    if remaining > 0:
        preview += f", ... (+{remaining} more)"

    count = f"{len(d)} item{'s' if len(d) != 1 else ''}"
    return " ".join(f"dict: {count} | {preview}".splitlines())
```

